//! The plan sources, against the golden file the Python reference produced.
//!
//! `crates/stride-core/tests/fixtures/plan_sources/expected.json` is
//! generated by `make_expected.py`, which calls the reference implementation
//! (`backend/app/services/plan_sources.py`) — the same rule every other
//! crate in this workspace follows: the Python is the reference, and the
//! Rust port is measured against it.
//!
//! The comparison follows `docs/core-contract.md` §8: strings, booleans,
//! nulls and integers are exactly equal; floating point numbers differ by at
//! most `1e-9 × max(1, |golden value|)`.

// An integration test is its own crate, so the workspace's
// `allow-*-in-tests` configuration does not reach it: a test that cannot
// unwrap a fixture it just read is a worse test.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::{Path, PathBuf};

use serde_json::Value;

use stride_core::model::{Activity, PlanSession};
use stride_core::plan_sources::{
    baseline_verdict, infer_plan, normalise_date, sessions_from_workouts, workouts_plan,
    ScheduledWorkout, WorkoutDetail,
};

/// The plan-source fixtures.
fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("plan_sources")
}

fn read_json(name: &str) -> Value {
    let path = fixture_dir().join(name);
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
    serde_json::from_str(&text)
        .unwrap_or_else(|error| panic!("cannot parse {}: {error}", path.display()))
}

/// Compare a computed value with a golden value, using the contract's rules.
fn assert_same(actual: &Value, expected: &Value, path: &str) {
    match (actual, expected) {
        (Value::Number(left), Value::Number(right)) => {
            let left = left.as_f64().unwrap_or(f64::NAN);
            let right = right.as_f64().unwrap_or(f64::NAN);
            let tolerance = 1e-9 * f64::max(1.0, right.abs());
            assert!(
                (left - right).abs() <= tolerance,
                "{path}: computed {left}, golden {right} (tolerance {tolerance})"
            );
        }
        (Value::Array(left), Value::Array(right)) => {
            assert_eq!(
                left.len(),
                right.len(),
                "{path}: computed {} items, golden {} items",
                left.len(),
                right.len()
            );
            for (index, (left, right)) in left.iter().zip(right.iter()).enumerate() {
                assert_same(left, right, &format!("{path}[{index}]"));
            }
        }
        (Value::Object(left), Value::Object(right)) => {
            let left_keys: Vec<&String> = left.keys().collect();
            let right_keys: Vec<&String> = right.keys().collect();
            assert_eq!(
                left_keys, right_keys,
                "{path}: computed and golden have different keys"
            );
            for (key, right) in right {
                let left = left
                    .get(key)
                    .unwrap_or_else(|| panic!("{path}: missing key {key}"));
                assert_same(left, right, &format!("{path}.{key}"));
            }
        }
        _ => assert_eq!(actual, expected, "{path}: computed and golden differ"),
    }
}

/// The activities of a fixture case.
fn activities(case: &Value) -> Vec<Activity> {
    case["activities"]
        .as_array()
        .expect("the activities")
        .iter()
        .enumerate()
        .map(|(index, spec)| {
            let mut activity: Activity = serde_json::from_value(spec.clone()).expect("an activity");
            activity.id = index as i64 + 1;
            activity
        })
        .collect()
}

/// The plan of a fixture case, as the Rust port computes it.
fn inferred(case: &Value) -> Value {
    let activities = activities(case);
    let from = case["from"].as_str().expect("a from");
    let to = case["to"].as_str().expect("a to");
    serde_json::to_value(infer_plan(&activities, from, to)).expect("the plan")
}

#[test]
fn the_inferred_plan_matches_the_golden_file() {
    let inputs = read_json("inputs.json");
    let golden = read_json("expected.json");
    assert_same(
        &inferred(&inputs["inferred"]),
        &golden["inferred"],
        "plan_sources.inferred",
    );
}

#[test]
fn a_history_that_is_too_thin_declines_and_says_why() {
    let inputs = read_json("inputs.json");
    let golden = read_json("expected.json");
    assert_same(
        &inferred(&inputs["inferred_thin"]),
        &golden["inferred_thin"],
        "plan_sources.inferred_thin",
    );

    let plan = infer_plan(
        &activities(&inputs["inferred_thin"]),
        inputs["inferred_thin"]["from"].as_str().unwrap(),
        inputs["inferred_thin"]["to"].as_str().unwrap(),
    );
    assert!(!plan.sufficient);
    assert!(plan.sessions.is_empty());
    assert!(plan.rest_days.is_empty());
    assert!(plan.long_run_day.is_none());
    assert!(plan.quality_day.is_none());
    assert!(plan.usual_by_weekday.is_empty());
    let reason = plan.reason.expect("a reason");
    assert!(reason.contains("14 runs over 4 weeks"), "{reason}");
    assert!(reason.contains("at least 12 runs over 8 weeks"), "{reason}");
}

#[test]
fn the_garmin_plan_matches_the_golden_file() {
    let inputs = read_json("inputs.json");
    let golden = read_json("expected.json");

    let scheduled: Vec<ScheduledWorkout> =
        serde_json::from_value(inputs["workouts"]["scheduled"].clone()).expect("the workouts");
    let details: Vec<WorkoutDetail> =
        serde_json::from_value(inputs["workouts"]["details"].clone()).expect("the details");

    let computed = serde_json::to_value(workouts_plan(&scheduled, &details)).expect("the plan");
    assert_same(&computed, &golden["workouts"], "plan_sources.workouts");

    // The source says which kind of plan it is, so the screen cannot mix a
    // baseline with a prescription.
    let plan = workouts_plan(&scheduled, &details);
    assert_eq!(plan.source, "garmin");
    assert!(plan.prescribed);

    // The cycling workout, the cancelled workout and the workout with no
    // date are not plan sessions.
    let dates: Vec<&str> = plan
        .sessions
        .iter()
        .map(|session| session.date.as_str())
        .collect();
    assert_eq!(
        dates,
        vec!["2026-03-02", "2026-03-04", "2026-03-07", "2026-03-08"]
    );
}

#[test]
fn an_inferred_plan_is_a_baseline_and_never_a_prescription() {
    let inputs = read_json("inputs.json");
    let activities = activities(&inputs["inferred"]);
    let plan = infer_plan(
        &activities,
        inputs["inferred"]["from"].as_str().unwrap(),
        inputs["inferred"]["to"].as_str().unwrap(),
    );
    assert_eq!(plan.source, "inferred");
    assert!(!plan.prescribed);
    assert!(plan.description.contains("baseline"));
    assert!(plan.description.contains("not a prescription"));
}

#[test]
fn the_window_excludes_the_range_it_is_compared_against() {
    let inputs = read_json("inputs.json");
    let activities = activities(&inputs["inferred"]);
    let plan = infer_plan(&activities, "2026-03-02", "2026-03-08");

    // The window is the twelve whole weeks that end before the range.
    assert_eq!(plan.window_start.as_deref(), Some("2025-12-08"));
    assert_eq!(plan.window_end.as_deref(), Some("2026-03-01"));

    // The fixture runs 11 km on the Tuesday of the range itself. The usual
    // Tuesday is the median of the twelve weeks before it, not 11 km.
    let tuesday = plan
        .sessions
        .iter()
        .find(|session| session.date == "2026-03-03")
        .expect("the Tuesday session");
    assert_eq!(tuesday.target_distance_m, Some(10500.0));
    assert_ne!(tuesday.target_distance_m, Some(11000.0));
}

#[test]
fn a_walk_is_not_a_run_and_an_empty_run_says_nothing() {
    let inputs = read_json("inputs.json");
    let activities = activities(&inputs["inferred"]);
    let plan = infer_plan(&activities, "2026-03-02", "2026-03-08");

    // The fixture walks on the Wednesday and logs an empty run on the
    // Friday: both are rest days.
    assert_eq!(plan.rest_days, vec!["Wednesday", "Friday"]);

    // The Saturday shakeout happens twice in twelve weeks: occasional, not
    // a habit, so it is not a session and not a rest day either.
    assert!(!plan.rest_days.contains(&"Saturday".to_string()));
    assert!(plan
        .sessions
        .iter()
        .all(|session| session.date != "2026-03-07"));
}

#[test]
fn the_baseline_verdict_says_less_than_usual_and_never_missed() {
    let session = PlanSession {
        id: 0,
        date: "2026-03-08".to_string(),
        session_type: "long".to_string(),
        title: Some("Your usual long run".to_string()),
        details: None,
        target_distance_m: Some(12000.0),
        pace_low_s_km: Some(300.0),
        pace_high_s_km: Some(320.0),
    };

    // Four kilometres against a usual twelve.
    let short = baseline_verdict(&session, Some(&activity(4000.0, 1300.0)));
    assert_eq!(short.verdict, "less_than_usual");
    assert_eq!(short.verdict_label, "less than usual");
    assert_eq!(
        short.message,
        "You usually run 12.0 km on a Sunday; you ran 4.0 km, which is less than usual."
    );
    assert_eq!(short.usual_distance_m, Some(12000.0));
    assert_eq!(short.actual_distance_m, Some(4000.0));
    assert_eq!(short.delta_m, Some(-8000.0));

    // Nothing logged at all is still less than usual — never "missed".
    let nothing = baseline_verdict(&session, None);
    assert_eq!(nothing.verdict, "less_than_usual");
    assert!(nothing.message.contains("nothing was logged"));

    // Fifteen kilometres against a usual twelve.
    let more = baseline_verdict(&session, Some(&activity(15000.0, 4800.0)));
    assert_eq!(more.verdict, "more_than_usual");
    assert_eq!(more.verdict_label, "more than usual");

    // Twelve kilometres is a usual day.
    let usual = baseline_verdict(&session, Some(&activity(12000.0, 3900.0)));
    assert_eq!(usual.verdict, "on_a_usual_day");
    assert_eq!(usual.verdict_label, "on a usual day");

    // The tolerance is ten per cent either side.
    let just_inside = baseline_verdict(&session, Some(&activity(12900.0, 4200.0)));
    assert_eq!(just_inside.verdict, "on_a_usual_day");
    let just_outside = baseline_verdict(&session, Some(&activity(13400.0, 4400.0)));
    assert_eq!(just_outside.verdict, "more_than_usual");
}

#[test]
fn a_session_without_a_baseline_says_so() {
    let session = PlanSession {
        id: 0,
        date: "2026-03-08".to_string(),
        session_type: "easy".to_string(),
        title: None,
        details: None,
        target_distance_m: None,
        pace_low_s_km: None,
        pace_high_s_km: None,
    };
    let verdict = baseline_verdict(&session, Some(&activity(4000.0, 1300.0)));
    assert_eq!(verdict.verdict, "no_usual_session");
    assert_eq!(verdict.usual_distance_m, None);
    assert_eq!(verdict.delta_m, None);
}

/// A run, for the verdict tests.
fn activity(distance_m: f64, moving_time_s: f64) -> Activity {
    Activity {
        id: 1,
        name: "run".to_string(),
        local_date: "2026-03-08".to_string(),
        start_date: "2026-03-08".to_string(),
        sport_type: "running".to_string(),
        source: "garmin".to_string(),
        distance_m,
        moving_time_s: Some(moving_time_s),
        ..Activity::default()
    }
}

#[test]
fn a_calendar_date_is_read_in_every_shape_garmin_sends() {
    assert_eq!(normalise_date("2026-03-08"), Some("2026-03-08".to_string()));
    assert_eq!(
        normalise_date("2026-03-08T00:00:00.0"),
        Some("2026-03-08".to_string())
    );
    assert_eq!(normalise_date(""), None);
    assert_eq!(normalise_date("not a date"), None);
    // An epoch in seconds and an epoch in milliseconds are the same day.
    assert_eq!(
        normalise_date("1772400000"),
        normalise_date("1772400000000")
    );
}

#[test]
fn a_workout_without_a_detail_still_becomes_a_session() {
    let scheduled = vec![ScheduledWorkout {
        workout_id: Some("900".to_string()),
        name: Some("Trail run".to_string()),
        date: Some("2026-03-07".to_string()),
        sport: Some("trail_running".to_string()),
        status: Some("scheduled".to_string()),
    }];
    let sessions = sessions_from_workouts(&scheduled, &[]);
    assert_eq!(sessions.len(), 1);
    assert_eq!(sessions[0].date, "2026-03-07");
    assert_eq!(sessions[0].session_type, "easy");
    assert_eq!(sessions[0].title.as_deref(), Some("Trail run"));
    assert_eq!(sessions[0].target_distance_m, None);
}
